INSERT INTO lesson_transcripts (id, audio_url, content, lesson_id, order_index, title, khmer_content) VALUES (33, '/uploads/audio/1790611893123_a27f091e_EG10_UNIT_1.A_3.A__High_quality_.mp3', '1.A_3A Listen and write the number you hear
1. Fifteen  2. ninety   3. sixty  4. eighteen 5. I am fourteen  6. My dad is fifty
7. Meng and Sothea are thirteen.    9. It''s Oudom''s birthday. He''s seventy. 
