INSERT INTO lesson_transcripts (id, audio_url, content, lesson_id, order_index, title, khmer_content) VALUES (130, '/uploads/audio/1790758175191_68ca2ec6_EG10_UNIT_3.A_2.A__High_quality_.mp3', 'Kosal: Hi, Tim! Welcome to my house!
Tim: Hey, Kosal!
Kosal: Let''s me show you around. This is the kitchen. There are two cupboards.
Tim: They''re big!
Kosal: Oh, and there is a refrigerator.
Tim: Of course. And it''s full of food!
Kosal: Now this is the living room. There is a sofa for us to sit and watch TV, and there is also a fan. Oh! Look over there, there is a table, and there are four chairs for us to
have our meals.
Tim: Nice. Is that your bedroom?
Kosal: Yes, it is. There is a bed, a desk and a chair.
Tim: Wow! You have five football posters!
Kosal: Yes, I do. I look like the player right?
Tim: Is there a mirror in the bathroom?
Kosal: Yes, there is.
Tim: Go and have a look', 97, 2, 'Transcript 2:  3A,2A Listening: Tim visits Kosal''s house. Listen and fill in the gaps. Write the answers in your notebook.', 'កុសល៖ សួស្តី ធីម! សូមស្វាគមន៍មកកាន់ផ្ទះរបស់ខ្ញុំ!
ធីម៖ ហ៊ឺ កុសល!
កុសល៖ ចាំខ្ញុំបង្ហាញអ្នកជុំវិញ។ នេះគឺជាផ្ទះបាយ។ មានទូដាក់ចានពីរ។
ធីម៖ គេធំហើយ!
កុសល៖ អូ៎ ហើយមានទូរទឹកកក
ធីម៖ ពិតណាស់។ ហើយ​វា​ពេញ​ដោយ​អាហារ​!
កុសល៖ ឥឡូវនេះជាបន្ទប់ទទួលភ្ញៀវ។ មានសាឡុងសម្រាប់អង្គុយមើលទូរទស្សន៍ ហើយមានកង្ហារមួយផងដែរ។ អូ! មើលទៅទីនោះមានតុមួយ ហើយមានកៅអីបួនសម្រាប់ពួកយើង
មានអាហាររបស់យើង។
ធីម៖ ល្អណាស់។ តើនោះជាបន្ទប់គេងរបស់អ្នកទេ?
កុសល៖ បាទ។ មានគ្រែមួយ តុ និងកៅអី។
ធីម៖ អីយ៉ា! អ្នកមានផ្ទាំងរូបភាពបាល់ទាត់ចំនួនប្រាំ!
កុសល៖ បាទ ខ្ញុំ​ធ្វើ។ ខ្ញុំមើលទៅដូចអ្នកលេងមែនទេ?
Tim: មានកញ្ចក់ក្នុងបន្ទប់ទឹកទេ?
កុសល៖ បាទ មាន។
ធីម៖ ទៅមើល') ON CONFLICT (id) DO NOTHING;
